const reasonKO=['부분 납품 — 잔량 추후 도착','공급업체 출하 부족','운송 중 손실','유출 또는 누출','포장 손상','오염 또는 품질 불합격','잘못된 등급, 규격 또는 제품','초과 납품','중량 차이','계수 또는 측정 차이','기타'],parties=['Supplier','Company','Carrier / Insurer','Pending Investigation'],methods=['Later Delivery','Replacement','Invoice Reduction','Purchase Credit','Cash Refund','Company Loss'];
const L=v=>currentLanguage==='ko'?(labels[v]||t(v)):v,may=(m,a='create')=>me?.role==='CEO / Owner'||typeof canDo==='function'&&canDo(m,a),reasonLabel=v=>currentLanguage==='ko'&&state?.reasons?.includes(v)?reasonKO[state.reasons.indexOf(v)]:L(v);
let state=null,claim=null,dialogContext=null,busy=false,collecting=false,pending=null,epoch=0;const evidenceCache=new Map();
const field=(name,en,ko,value='',attrs='')=>`<label class="field"><span>${E(T(en,ko))}</span><input class="form-control" name="${E(name)}" value="${E(value??'')}" ${attrs}></label>`;
