const btn=(en,ko,action,cls='')=>`<button type="button" class="btn ${cls}" onclick="BOMReceiving44.${action}">${E(T(en,ko))}</button>`;
const err=()=>'<p class="rc-error" data-rc-error role="alert" tabindex="-1"></p>',fd=form=>Object.fromEntries(new FormData(form)),json=(s,d={})=>{try{return JSON.parse(s||JSON.stringify(d))}catch(_){return d}},get=(root,name)=>root.querySelector('[name="'+name+'"]'),values=root=>Object.fromEntries([...root.querySelectorAll('[name]')].map(x=>[x.name,x.value]));
function decorate(){window.BOMUI?.decorate();}
function page(title,body){openWorkflowHtmlV324(`<div class="receiving44" data-receiving44>${body}</div>`,{title,context:T('Pink Salt','핑크 소금')});decorate();formDirty=false;}
function error(e){const p=document.activeElement?.closest('form')?.querySelector('[data-rc-error]')||[...document.querySelectorAll('#modalRoot [data-rc-error]'),...document.querySelectorAll('[data-receiving44] [data-rc-error]')].find(x=>x.offsetParent!==null);if(p){p.textContent=t(e.message||String(e));p.focus();p.scrollIntoView({block:'center'})}else toast(t(e.message||String(e)))}
const operationStore=()=> 'bo_receiving_operation44:'+me?.id+':'+selectedUnitId;
function savedOperation(){try{return JSON.parse(sessionStorage.getItem(operationStore())||'null')}catch(_){return null}}
function saveOperation(o){sessionStorage.setItem(operationStore(),JSON.stringify(o))}
function clearOperation(){sessionStorage.removeItem(operationStore());pending=null}
async function recover(){const o=savedOperation();if(!o)return;try{const d=await api('/api/pink-salt/operations/'+encodeURIComponent(o.key)),found=d.operations?.find(x=>x.route==='POST '+B+o.url);if(found){clearOperation();toast(found.status==='Pending Approval'?T('The previous request is awaiting approval.','이전 요청은 승인 대기 중입니다.'):T('The previous request was recorded. Showing the saved result.','이전 요청이 기록되었습니다. 저장된 결과를 표시합니다.'));return found;}}catch(_){}return null;}
async function mutate(url,body,summary=''){if(busy)return null;busy=true;try{if(!await confirmAction({title:T('Review & Confirm','검토 및 확인'),message:summary||T('Review quantities, responsibility and financial effects. This action will be recorded in history.','수량, 책임 및 재무 영향을 검토하세요. 이 작업은 이력에 기록됩니다.'),confirmLabel:T('Confirm','확인'),cancelLabel:T('Keep Editing','계속 편집')}))return null;const signature=url+JSON.stringify(body),digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(signature)))].map(x=>x.toString(16).padStart(2,'0')).join(''),old=savedOperation();if(pending?.signature!==digest)pending={signature:digest,key:old?.signature===digest&&old.url===url?old.key:crypto.randomUUID()};saveOperation({...pending,url});const r=await api(B+url,{method:'POST',headers:{'Content-Type':'application/json','X-Idempotency-Key':pending.key},body:JSON.stringify({...body,idempotency_key:pending.key})});clearOperation();formDirty=false;if(r.approval_required)toast(T('Submitted for approval. No stock or financial change has executed.','승인 요청이 제출되었습니다. 재고 또는 재무 변경은 아직 실행되지 않았습니다.'));return r}finally{busy=false}}

const source=(type,id,extra={})=>BOMRouter.navigate(type==='import'?'psImports':'psPackaging','receive',id,'',{params:extra}),caseRoute=id=>BOMRouter.navigate('psSuppliers','claim',id),purchase=(type,id)=>{formDirty=false;return BOMRouter.navigate(type==='import'?'psImports':'psPackaging',type==='import'?'import':'purchase',id)},supplier=id=>BOMRouter.navigate('psSuppliers','supplier',id,'claims');
function evidenceLinks(items){return `<div class="rc-evidence">${items.map(x=>`<a class="btn small" href="${E(x.path||'/uploads/'+x.file)}" target="_blank" rel="noopener">${E(x.name||x.file)}</a>`).join('')}</div>`}
async function upload(files,p){const all=[];for(const file of files){const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join(''),key=p.source_type+':'+p.id+':'+digest;if(!evidenceCache.has(key)){const data=new FormData();data.set('source_type',p.source_type);data.set('source_id',p.id);data.set('file',file);const promise=multipartApi(B+'/evidence',data).catch(e=>{evidenceCache.delete(key);throw e});evidenceCache.set(key,promise);}all.push(await evidenceCache.get(key));}return all}

function summary(c){const units=[...new Set(c.lines.map(l=>l.unit))];return `<div class="rc-summary">${[['Ordered','주문','ordered_q'],['Physically received','실물 입고','previous_q'],['Open quantity','미납 수량','open_q'],['Accepted receipts','합격 입고','accepted_q'],['Quarantined','격리','quarantine_q'],['Rejected','거부','rejected_q']].map(([en,ko,k])=>`<div class="card"><small>${E(T(en,ko))}</small>${units.map(u=>`<strong>${N(Q(c.lines.filter(l=>l.unit===u).reduce((n,l)=>n+l[k],0)))} ${E(u)}</strong>`).join('')}</div>`).join('')}</div>`}
function receiptLine(l){const isImport=state.purchase.source_type==='import',cap=Q(l.open_q),bags=isImport?l.remaining_bags:0;return `<section class="card rc-line rc-simple-line" data-rc-line="${l.id}"><label class="pack-check"><input type="checkbox" name="selected" checked onchange="BOMReceiving44.line(this)"><strong>${E(currentLanguage==='ko'?(l.name_ko||l.name):l.name)}</strong></label><div class="rc-line-facts"><span>${E(T('Ordered','주문'))}: ${N(Q(l.ordered_q))} ${E(l.unit)}</span><span>${E(T('Previously received','이전 입고'))}: ${N(Q(l.previous_q))}</span><span>${E(T('Remaining to receive','입고 가능 잔량'))}: <b>${N(cap)} ${E(l.unit)}</b></span>${isImport?`<span>${E(T('Expected bags','예상 포대'))}: ${N(bags)}</span>`:''}${l.held_q?`<span class="badge">${E(T('Investigation hold','조사 보류'))}: ${N(Q(l.held_q))}</span>`:''}</div><div class="grid g2" data-rc-entry oninput="BOMReceiving44.line(this)">${isImport?`<input type="hidden" name="expected_bags" value="${bags}">${field('actual_bags','Bags received now','이번 입고 포대','','type="number" min="0" step="1" required')}`:''}${num('physical',isImport?'Net weight received now (kg)':'Quantity received now ('+l.unit+')',isImport?'이번 입고 순중량 (kg)':'이번 입고 수량 ('+l.unit+')','','required')}${sel('condition','Condition','상태',[['good',T('Good','양호')],['affected',T('Some damaged / inspection needed','일부 손상 / 검사 필요')]],'good','onchange="BOMReceiving44.line(this)"')}</div><div class="grid g2" data-rc-quality hidden>${num('quarantine','Hold for inspection','검사 보류',0)}${num('rejected','Reject / return','거부 / 반품',0)}</div><div class="rc-difference" data-rc-differences hidden><p data-rc-reconciliation role="status"></p>${sel('missing_action','What should happen to the missing balance?','누락 잔량을 어떻게 처리할까요?',[['',T('Choose…','선택…')],['later',T('Arriving later','추후 입고 예정')],['investigate',T('Needs investigation / possible claim','조사 필요 / 클레임 검토')],['split',T('Part arriving later, part needs investigation','일부 추후 입고, 일부 조사')]],'','onchange="BOMReceiving44.line(this)"')}<div data-rc-split hidden>${num('investigate_quantity','Quantity to investigate ('+l.unit+')','조사할 수량 ('+l.unit+')',0)}<small>${E(T('The rest stays pending delivery.','나머지는 추후 입고 대기로 유지됩니다.'))}</small></div><p class="muted" data-rc-hold-note hidden>${E(T('Goods received now will be saved. The disputed missing balance will be held and a linked investigation task will be created.','이번에 받은 물품은 저장됩니다. 분쟁 중인 누락 잔량은 보류되고 연결된 조사 작업이 생성됩니다.'))}</p></div></section>`}
async function receiving(type,id){const ticket=++epoch;await recover();const c=await api(B+'/'+type+'/'+id+'/context');if(ticket!==epoch)return;state=c;claim=null;const replacement=Number(new URLSearchParams(location.hash.split('?')[1]||'').get('replacement'));if(replacement){const s=c.settlements.find(s=>s.id===replacement);if(!s)throw Error(T('Approved delivery not found.','승인된 납품을 찾을 수 없습니다.'));const cs=c.cases.find(x=>x.id===s.case_id),used=c.receipts.filter(r=>r.replacement_id===s.id).flatMap(r=>r.lines).reduce((n,l)=>n+l.state.Accepted+l.state.Quarantined,0);c.lines=c.lines.filter(l=>l.id===cs.source_line_id).map(l=>({...l,open_q:Math.max(0,s.quantity_q-used),held_q:0,remaining_bags:Math.ceil(Math.max(0,s.quantity_q-used)/10000/l.conversion)}));c.replacement_id=s.id;c.can_receive=c.lines.some(l=>l.open_q>0);}const p=c.purchase,eligible=c.lines.filter(l=>l.open_q>0),issues=c.receiving_issues||[];page(T(c.can_receive?'Receive Goods':'Receiving History',c.can_receive?'물품 입고':'입고 이력')+' · '+p.purchase_no,`<div class="actions">${btn('Back to Purchase','구매로 돌아가기',`purchase('${type}',${id})`)}${btn('Supplier Profile','공급업체 프로필',`supplier(${p.supplier_id})`)}</div><p class="muted">${E(T('Select the categories in this delivery and enter what actually arrived.','이번 납품의 항목을 선택하고 실제 도착 수량을 입력하세요.'))}</p>${c.can_receive&&may('inventory')?`<form data-bom-no-review="1" onsubmit="BOMReceiving44.saveReceipt(event)"><div class="card"><div class="grid g2" data-rc-header>${field('receipt_date','Receiving date','입고일',new Date().toISOString().slice(0,10),'type="date" required')}${sel('location_id','Warehouse / location','창고 / 위치',[['',T('Select…','선택…')],...c.locations.map(l=>[l.id,[l.warehouse,l.zone,l.rack_bin].filter(Boolean).join(' · ')])],'','required')}</div><div class="actions">${btn('Fill Expected Quantities','예상 수량 입력','prefill()','primary')}<button type="button" class="btn" onclick="BOMQA43.refreshLocations(this.form)">${E(T('Refresh Locations','위치 새로고침'))}</button></div></div>${eligible.map(receiptLine).join('')}<details class="card"><summary>${E(T('Notes, photos & follow-up (optional)','메모, 사진 및 후속 조치 (선택)'))}</summary>${field('notes','Receiving notes','입고 메모')}<label class="field"><span>${E(T('Photos / documents','사진 / 문서'))}</span><input type="file" name="evidence" multiple accept="image/*,.pdf"></label>${sel('assigned_to','Assign investigation to','조사 담당자',[['',T('Me','나')],...c.employees.map(u=>[u.id,u.name])])}${field('follow_up','Follow-up date','후속 조치일','','type="date"')}</details><label class="pack-check"><input type="checkbox" name="physical_checked" required><span>${E(T('I checked the delivered quantities and condition.','납품 수량과 상태를 확인했습니다.'))}</span></label>${err()}<div class="rc-footer">${btn('Cancel','취소',`purchase('${type}',${id})`)}<button type="submit" class="btn primary">${E(T('Review & Receive','검토 및 입고'))}</button></div></form>`:`<div class="card"><b>${E(T('No quantity is currently eligible for receiving.','현재 입고 가능한 수량이 없습니다.'))}</b><p>${E(T('All goods are received, formally resolved, or held for investigation. Open a pending issue below for authorized deliveries.','모든 물품이 입고 또는 정식 해결되었거나 조사 보류 중입니다. 승인된 납품은 아래 미결 문제에서 여세요.'))}</p></div>`}${issueCards(issues)}<details class="card"><summary>${E(T('View Receiving History','입고 이력 보기'))}</summary>${receiptHistory(c)}<div class="actions">${btn('Download Receiving PDF','입고 PDF 다운로드',`report('${type}',${id},'pdf',this)`)}${btn('Download CSV','CSV 다운로드',`report('${type}',${id},'csv',this)`)}</div></details>`);}
function line(el){const row=el.closest('[data-rc-line]');if(!row)return;const selected=get(row,'selected').checked,l=state.lines.find(l=>l.id===Number(row.dataset.rcLine)),physical=Number(get(row,'physical').value||0),missing=Math.max(0,Q(l.open_q)-physical),bags=get(row,'actual_bags'),bagMissing=bags&&Math.max(0,Number(get(row,'expected_bags').value)-Number(bags.value||0)),diff=missing>0||bagMissing>0,quality=get(row,'condition').value==='affected';row.querySelectorAll('[data-rc-entry] input,[data-rc-entry] select').forEach(x=>x.disabled=!selected);row.querySelector('[data-rc-quality]').hidden=!selected||!quality;for(const n of ['quarantine','rejected'])get(row,n).disabled=!selected||!quality;row.querySelector('[data-rc-differences]').hidden=!selected||!diff;get(row,'missing_action').required=!!(selected&&diff);get(row,'missing_action').disabled=!selected||!diff;const action=get(row,'missing_action').value;row.querySelector('[data-rc-split]').hidden=action!=='split';get(row,'investigate_quantity').required=!!(selected&&diff&&action==='split');get(row,'investigate_quantity').disabled=!selected||!diff||action!=='split';get(row,'investigate_quantity').max=missing;row.querySelector('[data-rc-hold-note]').hidden=!['split','investigate'].includes(action);row.querySelector('[data-rc-reconciliation]').textContent=T('Missing: ','누락: ')+N(missing)+' '+l.unit+(bags?' · '+N(bagMissing)+' '+T('bags','포대'):'');row.classList.toggle('is-discrepant',!!(selected&&diff));formDirty=true;}
function prefill(){for(const row of document.querySelectorAll('[data-rc-line]')){if(!get(row,'selected').checked)continue;const l=state.lines.find(l=>l.id===Number(row.dataset.rcLine));get(row,'physical').value=Q(l.open_q);if(get(row,'actual_bags'))get(row,'actual_bags').value=get(row,'expected_bags').value;line(row)}}
async function saveReceipt(e){e.preventDefault();if(busy||collecting||!e.target.reportValidity())return;collecting=true;try{const f=e.target,b={...values(f.querySelector('[data-rc-header]')),version:state.version,replacement_id:state.replacement_id||null,physical_checked:f.elements.physical_checked.checked,notes:f.elements.notes.value,assigned_to:f.elements.assigned_to.value,follow_up:f.elements.follow_up.value,lines:[...f.querySelectorAll('[data-rc-line]')].filter(row=>get(row,'selected').checked).map(row=>{const l=state.lines.find(l=>l.id===Number(row.dataset.rcLine)),v=values(row);return {line_id:l.id,expected:Q(l.open_q),physical:v.physical,expected_bags:v.expected_bags,actual_bags:v.actual_bags,quarantine:v.condition==='affected'?v.quarantine:0,rejected:v.condition==='affected'?v.rejected:0,missing_action:v.missing_action,investigate_quantity:v.investigate_quantity}})};b.evidence=await upload(f.elements.evidence.files,state.purchase);const review=b.lines.map(x=>{const l=state.lines.find(l=>l.id===x.line_id);return l.name+': '+x.physical+' '+l.unit+' · '+T('Missing balance','누락 잔량')+': '+N(Math.max(0,Q(l.open_q)-Number(x.physical)))+' · '+(x.missing_action==='later'?T('Arriving later','추후 입고'):['split','investigate'].includes(x.missing_action)?T('Investigation task and receiving hold','조사 작업 및 입고 보류'):T('No missing balance','누락 잔량 없음'));}).join('\n');const result=await mutate('/simple/'+state.purchase.source_type+'/'+state.purchase.id+'/receipts',b,review);if(result){await purchase(state.purchase.source_type,state.purchase.id);toast(result.issue_id?T('Received goods saved. Investigation task created.','받은 물품이 저장되었습니다. 조사 작업이 생성되었습니다.'):T('Receiving saved.','입고가 저장되었습니다.'));}}catch(e){error(e)}finally{collecting=false}}
function packSummary(d){return `<section class="card receiving44"><h3>${E(T('Physical receiving and quality disposition','실물 입고 및 품질 처리'))}</h3><div class="table-wrap"><table class="table"><thead><tr>${[['Material','자재'],['Unit','단위'],['Ordered','주문'],['Physical receipts','실물 입고'],['Accepted receipts','합격 입고'],['Quarantined','격리'],['Rejected','거부'],['Open','미납']].map(x=>`<th>${E(T(...x))}</th>`).join('')}</tr></thead><tbody>${d.lines.map(l=>{const p=d.unified_receiving.lines[l.id]||{};return `<tr><td>${E(l.snapshot.sku)}</td><td>${E(l.snapshot.unit)}</td>${['ordered','physical','accepted','quarantine','rejected','open'].map(k=>`<td>${N(Q(p[k]))}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>${btn(d.unified_receiving.open_q>0?'Receive Goods':'View Receiving History',d.unified_receiving.open_q>0?'물품 입고':'입고 이력 보기',`source('packaging',${d.id})`,'primary')}</section>`}
function receiptHistory(c){return `<section class="card"><h3>${E(T('Receiving history and inventory disposition','입고 이력 및 재고 처리'))}</h3>${c.receipts.map(r=>`<details><summary>${E(r.receipt_no)} · ${E(r.receipt_date)} · ${E(r.reference)}</summary>${evidenceLinks(json(r.evidence_json,[]))}${r.lines.map(l=>`<div class="card"><b>${E(currentLanguage==='ko'?(l.snapshot.name_ko||l.snapshot.name):l.snapshot.name)}</b><p>${E(T('Original physical quantity','원래 실물 수량'))}: ${N(Q(l.physical_q))} ${E(l.snapshot.unit)}${l.actual_bags!==null?' · '+N(l.actual_bags)+' '+E(T('bags','포대')):''}</p><div class="actions">${Object.entries(l.state).map(([k,v])=>`<span class="badge">${E(L(k))}: ${N(Q(v))}</span>`).join('')}</div>${may('inventory','edit')?`<div class="actions">${Object.entries({'Quarantine Accepted':['Accepted'], 'Release Quarantine':['Quarantined'],'Reject Quarantine':['Quarantined'],'Return Accepted':['Accepted'],'Return Rejected':['Rejected'],'Dispose Quarantine':['Quarantined'],'Dispose Rejected':['Rejected']}).filter(([,keys])=>l.state[keys[0]]>0).map(([action,keys])=>btn(action,L(action),`disposition(${l.id},'${action}',${Q(l.state[keys[0]])})`)).join('')}</div>`:''}${l.discrepancies.map(d=>`<p>${E(reasonLabel(d.reason))} · ${E(L(d.classification))} · ${N(Q(d.quantity_q))} ${E(d.dimension==='bags'?T('bags','포대'):l.snapshot.unit)} · ${E(d.notes||'')}</p>`).join('')}</div>`).join('')}${may('inventory','edit')?btn('Reverse / Correct Receipt','입고 취소 / 수정',`reverse('receipts',${r.id})`):''}</details>`).join('')||`<p>${E(T('No receiving records yet.','입고 기록이 없습니다.'))}</p>`}</section>`}
function caseTable(cases){return `<section class="card"><h3>${E(T('Claims & Adjustments','클레임 및 조정'))}</h3><div class="table-wrap"><table class="table"><thead><tr>${[['Case','클레임'],['Status','상태'],['Claim value','클레임 금액'],['Action','작업']].map(x=>`<th>${E(T(...x))}</th>`).join('')}</tr></thead><tbody>${cases.map(c=>`<tr><td>${E(c.case_no)}<br>${E(reasonLabel(c.title))}</td><td>${E(L(c.status))}</td><td>${E(c.currency)} ${N(C(c.claim_cents))}</td><td>${btn('Open','열기',`case(${c.id})`)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function supplierPanel(id){const [d,issues]=await Promise.all([api(B+'/suppliers/'+id),api(B+'/supplier/'+id+'/issues')]),root=document.getElementById('ps315SupplierPanel');if(!root)return;if(Number(window.__ps315SupplierAccount?.supplier.id)!==Number(id))return;document.querySelectorAll('[data-ps315-tab]').forEach(b=>b.classList.toggle('primary',b.dataset.ps315Tab==='claims'));root.innerHTML=`<div class="receiving44">${issueCards(issues)}<details><summary>${E(T('Credits, refunds & historical claims','크레딧, 환불 및 과거 클레임'))}</summary><div class="rc-summary">${d.currencies.map(c=>`<div class="card"><b>${E(c.currency)}</b><p>${E(T('Available adjustment credit','사용 가능 조정 크레딧'))}: ${N(C(c.credit_cents))}</p><p>${E(T('Reserved / on-hold adjustment credit','예약 / 보류 조정 크레딧'))}: ${N(C(c.reserved_credit_cents))}</p><p>${E(T('Supplier refunds due','공급업체 환불 예정액'))}: ${N(C(c.refund_due_cents))}</p><p>${E(T('Carrier recoveries due (separate)','운송사 회수 예정액 (별도)'))}: ${N(C(c.carrier_refund_due_cents))}</p></div>`).join('')}</div><p>${E(T('Cash advances remain separate in Advances & Payments. Credits are non-cash claims adjustments.','현금 선급금은 선급금 및 지급 탭에서 별도로 관리됩니다. 크레딧은 비현금 클레임 조정입니다.'))}</p>${btn('Supplier Claims PDF','공급업체 클레임 PDF',`report('suppliers',${id},'pdf',this)`)}${caseTable(d.cases.filter(c=>!issues.some(i=>i.lines.some(l=>l.case_id===c.id))))}</details></div>`;decorate();}
function dialog(title,body,action){modal(`<div class="receiving44"><h2>${E(title)}</h2><form data-bom-no-review="1" onsubmit="BOMReceiving44.${action}(event)">${body}${err()}<div class="actions">${btn('Cancel','취소','close()')}<button class="btn primary" type="submit">${E(T('Review & Confirm','검토 및 확인'))}</button></div></form></div>`);decorate();formDirty=false;}
function newCase(){dialogContext={action:'newCase'};dialog(T('Open Discrepancy Case','차이 클레임 생성'),`${sel('source_line_id','Purchase line','구매 항목',state.lines.map(l=>[l.id,l.name+' · '+l.unit]))}${sel('line_id','Related receipt line (optional)','관련 입고 항목 (선택)',[['',T('No receipt / undelivered goods','입고 없음 / 미납품')],...state.receipts.flatMap(r=>r.lines.map(l=>[l.id,r.receipt_no+' · '+l.snapshot.name]))])}${field('title','Reason / title','사유 / 제목','','required')}${num('quantity','Affected quantity','차이 수량',0,'required')}${sel('dimension','Measurement','측정',[['stock',T('Stock quantity / net weight','재고 수량 / 순중량')],...(state.purchase.source_type==='import'?[['bags',T('Bag count','포대 수')]]:[])])}${field('notes','Investigation notes','조사 메모')}`,'saveDialog');}
function disposition(id,action,max){dialogContext={action:'disposition',id,kind:action};const settlements=state.settlements.filter(s=>s.method==='Company Loss'&&s.status!=='Reversed');dialog(L(action),`${num('quantity','Quantity','수량',max,`max="${max}" required`)}${action.startsWith('Dispose')?sel('settlement_id','Approved company-loss settlement','승인된 회사 손실 정산',[['',T('Select…','선택…')],...settlements.map(s=>[s.id,s.id+' · '+s.currency+' '+C(s.amount_cents)])],'','required'):''}${field('movement_date','Date','날짜',new Date().toISOString().slice(0,10),'type="date" required')}${field('reason','Reason','사유','','required')}`,'saveDialog');}
function reverse(entity,id){dialogContext={action:'reverse',entity,id};dialog(T('Controlled Reversal','통제된 취소'),`<p>${E(T('Original facts remain in history. Dependent records and closed periods must be resolved first.','원래 사실은 이력에 유지됩니다. 연결된 기록 및 마감 기간을 먼저 해결해야 합니다.'))}</p>${field('reason','Reversal reason','취소 사유','','required')}`,'saveDialog');}
function reverseExcess(){dialogContext={action:'excess'};dialog(T('Reverse Excess Authorization','초과 승인 취소'),field('reason','Reason','사유','','required'),'saveDialog')}
function caseStatus(){dialogContext={action:'state'};dialog(T('Case Status','클레임 상태'),`${sel('status','Status','상태',['Open','Under Investigation','Disputed','Rejected','Closed'].map(s=>[s,L(s)]),claim.status)}${field('reason','Reason','사유','','required')}`,'saveDialog');}
async function saveDialog(e){e.preventDefault();if(!e.target.reportValidity())return;try{const b=fd(e.target),d=dialogContext;let result;if(d.action==='newCase')result=await mutate('/cases',{...b,source_type:state.purchase.source_type,source_id:state.purchase.id});if(d.action==='disposition')result=await mutate('/lines/'+d.id+'/disposition',{...b,action:d.kind});if(d.action==='reverse')result=await mutate('/'+d.entity+'/'+d.id+'/reverse',b);if(d.action==='excess')result=await mutate('/cases/'+claim.id+'/reverse-excess',b);if(d.action==='state')result=await mutate('/cases/'+claim.id+'/state',{...b,revision:claim.revision});if(result){closeModal(true);if(d.action==='newCase')await caseRoute(result.id);else if(claim&&d.entity!=='receipts'&&d.action!=='disposition')await openCase(claim.id);else if(state)await receiving(state.purchase.source_type,state.purchase.id)}}catch(e){error(e)}}
function remove(el){el.closest('[data-rc-discrepancy],[data-rc-party],[data-rc-plan]').remove();formDirty=true;if(document.querySelector('[data-rc-party]'))calculate();}
function partyRow(p={party:'Supplier',amount_cents:0}){return `<div class="rc-party" data-rc-party>${sel('party','Responsible party','책임 주체',parties.map(x=>[x,L(x)]),p.party,'onchange="BOMReceiving44.calculate()"')}${field('name','Party / organization name','책임 주체 / 기관명',p.name||'')}${field('amount','Liability amount','부담 금액',C(p.amount_cents),'type="number" min="0" step="0.01" required oninput="BOMReceiving44.calculate()"')}${field('percent','Percent','비율',0,'type="number" min="0" max="100" step="0.01" oninput="BOMReceiving44.percent(this)"')}${num('quantity','Liability quantity (optional)','책임 수량 (선택)',Q(p.quantity_q),'oninput="BOMReceiving44.quantityShare(this)"')}${btn('Remove','삭제','remove(this)')}</div>`}
function planRow(p={}){return `<div class="rc-plan" data-rc-plan>${sel('party','Responsible party','책임 주체',parties.filter(x=>x!=='Pending Investigation').map(x=>[x,L(x)]),p.party||'Supplier')}${sel('settlement_method','Settlement method','정산 방법',methods.map(x=>[x,L(x)]),p.method||'Purchase Credit')}${field('amount','Agreed amount','합의 금액',p.amount||0,'type="number" min="0" step="0.01" required')}${num('quantity','Physical obligation / loss quantity','실물 의무 / 손실 수량',p.quantity||0)}${field('due_date','Due date','예정일',p.due_date||'','type="date"')}${btn('Remove','삭제','remove(this)')}</div>`}
async function advancedCase(id){const ticket=++epoch;await recover();const c=await api(B+'/cases/'+id);if(ticket!==epoch)return;claim=c;const resolution=c.resolution,editing=['Open','Under Investigation','Proposed Resolution','Rejected','Disputed'].includes(c.status)&&(may('purchases','edit')||may('finance','edit')),ps=c.parties.length?c.parties:[{party:'Supplier',amount_cents:c.claim_cents},{party:'Company',amount_cents:0}],context=await api(B+'/'+c.source_type+'/'+c.source_id+'/context');if(ticket!==epoch)return;state=context;
 page(T('Discrepancy Case','차이 클레임')+' · '+c.case_no,`<div class="actions"><span class="badge">${E(L(c.status))}</span>${btn('Receiving','입고',`source('${c.source_type}',${c.source_id})`)}${btn('Supplier Profile','공급업체 프로필',`supplier(${c.supplier_id})`)}${btn('Claim PDF','클레임 PDF',`report('cases',${c.id},'pdf',this)`)}${btn('Claim CSV','클레임 CSV',`report('cases',${c.id},'csv',this)`)}</div><section class="card"><h3>${E(reasonLabel(c.title))}</h3><p>${N(Q(c.quantity_q))} ${E(c.dimension==='bags'?T('bags','포대'):context.lines.find(l=>l.id===c.source_line_id)?.unit||'')} · ${E(c.currency)} ${N(C(c.claim_cents))}</p><p>${E(c.notes)}</p>${evidenceLinks(json(c.evidence_json,[]))}</section>${editing?`<form data-bom-no-review="1" onsubmit="BOMReceiving44.saveCase(event)"><section class="card"><h3>${E(T('Responsibility and agreed value','책임 및 합의 금액'))}</h3><div class="grid g2">${field('claim_amount','Agreed claim value ('+c.currency+')','합의 클레임 금액 ('+c.currency+')',C(c.claim_cents),'type="number" min="0" step="0.01" required oninput="BOMReceiving44.calculate()"')}${field('recognition_rate','Valuation: KRW per '+c.currency,'평가: '+c.currency+'당 원화',c.recognition_rate||(c.currency==='KRW'?'1':''),'type="number" min="0.0001" step="0.0001" required')}</div>${c.invoice_estimate?field('value_change_reason','Reason if changing invoice-based estimate','송장 기준 예상액 변경 시 사유',c.resolution.value_change_reason||''):''}<label class="field"><span>${E(T('Supplier / company split (use exact inputs for precision)','공급업체 / 당사 분담 (정확한 값 입력 가능)'))}</span><input class="form-range" data-rc-slider type="range" min="0" max="100" step="1" value="100" oninput="BOMReceiving44.slider(this.value)"></label><div data-rc-parties>${ps.map(partyRow).join('')}</div>${btn('Add Responsible Party','책임 주체 추가','addParty()')}<div class="rc-bar" data-rc-bar aria-hidden="true"></div><div class="rc-summary" data-rc-calc></div><p data-rc-remaining role="status"></p></section><section class="card"><h3>${E(T('Settlement obligations','정산 의무'))}</h3><p>${E(T('Allocate each party’s agreed amount across methods. Physical replacements and financial compensation must not recover the same value twice.','각 책임 주체의 합의 금액을 정산 방법별로 배분하세요. 실물 대체품 및 재무 보상으로 같은 금액을 중복 회수할 수 없습니다.'))}</p><div data-rc-plans>${(resolution.settlements||[]).map(planRow).join('')}</div>${btn('Add Settlement Method','정산 방법 추가','addPlan()')}<details><summary>${E(T('Quantity closure, excess authorization and disputed remainder','수량 마감, 초과 승인 및 분쟁 잔액'))}</summary><div class="grid g2">${num('close_quantity','Formally close undelivered quantity','미납 수량 공식 마감',resolution.close_quantity||0)}${num('excess_quantity','Authorize excess stock quantity','초과 재고 수량 승인',resolution.excess_quantity||0)}${sel('excess_treatment','Excess delivery agreement','초과 납품 합의',[['',T('Select…','선택…')],['No Charge',T('Supplier confirms no charge','공급업체 무상 확인')],['Additional Payable',T('Additional supplier invoice / payable','추가 공급업체 송장 / 지급채무')]],resolution.excess_treatment||'')}${field('excess_invoice_amount','Additional invoice amount ('+c.currency+')','추가 송장 금액 ('+c.currency+')',resolution.excess_invoice_amount||0,'type="number" min="0" step="0.01"')}${field('disputed_amount','Disputed amount (separate linked case)','분쟁 금액 (별도 연결 클레임)',resolution.disputed_amount||0,'type="number" min="0" step="0.01"')}${num('disputed_quantity','Disputed quantity','분쟁 수량',resolution.disputed_quantity||0)}${field('dispute_reason','Dispute explanation','분쟁 설명',resolution.dispute_reason||'')}${field('linked_accounting_journal_id','Linked non-cash Accounting adjustment journal (optional)','연결된 비현금 회계 조정 분개 (선택)',resolution.linked_accounting_journal_id||'','type="number" min="1" step="1"')}<p>${E(T('Supplier recovery does not automatically include freight or customs. Link separately authorized inventory/cost adjustments where the approved policy requires them.','공급업체 회수액에 운임 또는 관세가 자동 포함되지 않습니다. 승인된 정책에 따라 별도 승인된 재고 / 원가 조정을 연결하세요.'))}</p></div><label class="pack-check"><input type="checkbox" name="additional_compensation" ${resolution.additional_compensation?'checked':''}><span>${E(T('Agreement explicitly authorizes additional compensation','합의에서 추가 보상을 명시적으로 승인함'))}</span></label>${field('additional_compensation_reason','Additional compensation justification','추가 보상 근거',resolution.additional_compensation_reason||'')}</details></section><section class="card"><div class="grid g2">${field('supplier_response','Supplier / carrier response','공급업체 / 운송사 답변',c.supplier_response)}${sel('assigned_to','Assigned employee','담당 직원',[['',T('Unassigned','미지정')],...(context.employees||[]).map(u=>[u.id,u.name])],c.assigned_to||'')}${field('follow_up','Follow-up date','후속 확인일',c.follow_up||'','type="date"')}${field('notes','Investigation / agreement notes','조사 / 합의 메모',c.notes)}</div><label class="field"><span>${E(T('Supporting evidence','관련 증빙'))}</span><input class="form-control" type="file" name="evidence" multiple accept="image/*,.pdf"></label></section>${err()}<div class="rc-footer"><button type="submit" class="btn primary">${E(T('Review & Save Proposal','제안 검토 및 저장'))}</button></div></form>`:''}${c.status==='Proposed Resolution'&&may('finance','edit')?`<div class="card actions">${btn('Submit Agreement for Authorization','합의 승인 요청',`agree(${c.revision})`,'primary')}</div>`:''}${settlementTable(c)}${resolution.excess_quantity&&may('finance','edit')?btn('Reverse Excess Authorization','초과 승인 취소','reverseExcess()'):''}${may('purchases','edit')||may('finance','edit')?btn('Change Case Status','클레임 상태 변경','caseStatus()'):''}${c.children.length?`<section class="card"><h3>${E(T('Linked disputed cases','연결된 분쟁 클레임'))}</h3>${c.children.map(x=>btn(x.case_no,x.case_no,`case(${x.id})`)).join('')}</section>`:''}${err()}<section class="card"><h3>${E(T('Approval history','승인 이력'))}</h3>${c.approvals.map(a=>`<p>#${a.id} · ${E(L(a.status))} · ${E(t(a.current_step||''))} ${btn('Open Approval','승인 열기',`approval(${a.id})`)}</p>`).join('')}</section><details class="card"><summary>${E(T('Audit history','감사 이력'))}</summary>${c.history.map(h=>`<p>${E(h.created_at)} · ${E(h.actor_name)} · ${E(L(h.action))} · ${E(h.reason===h.action?L(h.reason):h.reason)}</p>`).join('')}</details>`);
 if(editing){calculate();formDirty=false;}
}
function cents(v){return Number(BOMPackagingDecimal.fixed(String(v||0))/100n)}
function calculate(){const form=document.querySelector('[data-rc-parties]')?.closest('form');if(!form)return;try{const total=cents(get(form,'claim_amount').value),ps=[...form.querySelectorAll('[data-rc-party]')],items=ps.map(row=>({name:get(row,'name').value||L(get(row,'party').value),cents:cents(get(row,'amount').value)})),sum=items.reduce((n,p)=>n+p.cents,0),colors=['#066fd1','#f59f00','#2fb344','#ae3ec9'];ps.forEach((row,i)=>get(row,'percent').value=total?Math.round(items[i].cents*10000/total)/100:0);form.querySelector('[data-rc-bar]').innerHTML=items.map((p,i)=>`<span style="width:${Math.max(0,total?p.cents/total*100:0)}%;background:${colors[i%colors.length]}"></span>`).join('');form.querySelector('[data-rc-calc]').innerHTML=items.map(p=>`<div class="card"><small>${E(p.name)}</small><strong>${E(claim.currency)} ${N(C(p.cents))}</strong></div>`).join('');const remaining=form.querySelector('[data-rc-remaining]');remaining.textContent=T('Unallocated: ','미배분: ')+claim.currency+' '+N(C(total-sum));remaining.classList.toggle('rc-error',sum!==total);const slider=form.querySelector('[data-rc-slider]');slider.disabled=ps.length!==2||get(ps[0],'party').value!=='Supplier'||get(ps[1],'party').value!=='Company';slider.value=total?items[0].cents/total*100:0;formDirty=true;}catch(_){}}
function percent(input){const form=input.form,rows=[...form.querySelectorAll('[data-rc-party]')],row=input.closest('[data-rc-party]'),total=cents(get(form,'claim_amount').value),pct=Math.round(Number(input.value)*100);if(!Number.isSafeInteger(pct)||pct<0||pct>10000)return;const amount=Number((BigInt(total)*BigInt(pct)+5000n)/10000n);get(row,'amount').value=(amount/100).toFixed(2);if(rows.length===2)get(rows.find(r=>r!==row),'amount').value=((total-amount)/100).toFixed(2);calculate();}
function quantityShare(input){const q=Number(input.value),total=Q(claim.quantity_q);if(!total||q<0||q>total)return;const row=input.closest('[data-rc-party]'),share=get(row,'percent');share.value=(q/total*100).toFixed(2);percent(share)}
function slider(value){const p=document.querySelector('[data-rc-party] [name=percent]');p.value=value;percent(p)}
function addParty(){document.querySelector('[data-rc-parties]').insertAdjacentHTML('beforeend',partyRow({party:'Carrier / Insurer',amount_cents:0}));calculate();decorate();}
function addPlan(){document.querySelector('[data-rc-plans]').insertAdjacentHTML('beforeend',planRow());decorate();formDirty=true;}
async function saveCase(e){e.preventDefault();if(busy||collecting||!e.target.reportValidity())return;collecting=true;try{const b=fd(e.target);b.parties=[...e.target.querySelectorAll('[data-rc-party]')].map(values);b.revision=claim.revision;b.resolution={value_change_reason:b.value_change_reason,settlements:[...e.target.querySelectorAll('[data-rc-plan]')].map(row=>{const p=values(row);p.method=p.settlement_method;delete p.settlement_method;return p}),close_quantity:b.close_quantity,excess_quantity:b.excess_quantity,excess_treatment:b.excess_treatment,excess_invoice_amount:b.excess_invoice_amount,disputed_amount:b.disputed_amount,disputed_quantity:b.disputed_quantity,dispute_reason:b.dispute_reason,linked_accounting_journal_id:b.linked_accounting_journal_id||null,additional_compensation:e.target.elements.additional_compensation.checked,additional_compensation_reason:b.additional_compensation_reason};b.evidence=[...json(claim.evidence_json,[]),...await upload(e.target.elements.evidence.files,{source_type:claim.source_type,id:claim.source_id})];if(await mutate('/cases/'+claim.id+'/proposal',b,claim.case_no+'\n'+claim.currency+' '+b.claim_amount+'\n'+b.parties.map(p=>L(p.party)+': '+p.amount).join('\n')))await openCase(claim.id)}catch(e){error(e)}finally{collecting=false}}
async function agree(revision){try{if(await mutate('/cases/'+claim.id+'/agree',{revision,reason:T('Authorize the reviewed responsibility and settlement agreement.','검토한 책임 및 정산 합의를 승인합니다.')}))await openCase(claim.id)}catch(e){error(e)}}
function settlementTable(c){return `<section class="card"><h3>${E(T('Settlements, credits and refunds','정산, 크레딧 및 환불'))}</h3>${c.settlements.map(s=>`<div class="card"><div class="section-title"><div><b>${E(L(s.method))}</b><p>${E(L(s.party))} ${E(s.counterparty)} · ${E(s.currency)} ${N(C(s.amount_cents))} · ${E(L(s.status))}</p></div></div><p>${E(T('Remaining amount','잔액'))}: ${E(s.currency)} ${N(C(s.balance_cents))}${['Replacement','Later Delivery'].includes(s.method)?' · '+E(T('Unaccepted obligation','미승인 입고 의무'))+': '+N(Q(s.remaining_quantity_q)):''}</p><div class="actions">${s.status!=='Reversed'&&may('finance','edit')?btn('Reverse Settlement','정산 취소',`reverse('settlements',${s.id})`):''}${s.status!=='Reversed'&&s.method==='Purchase Credit'&&s.available_cents&&may('finance','edit')?btn('Apply Credit to Purchase','구매에 크레딧 적용',`credit(${s.id})`):''}${s.status!=='Reversed'&&s.method==='Cash Refund'&&s.available_cents&&may('finance')?btn('Record Actual Refund','실제 환불 입금 기록',`refund(${s.id})`):''}${s.status!=='Reversed'&&['Replacement','Later Delivery'].includes(s.method)&&s.available_delivery_q>0&&may('inventory')?btn('Receive Linked Delivery','연결 납품 입고',`source('${c.source_type}',${c.source_id},{replacement:${s.id}})`):''}</div>${s.allocations.map(a=>`<p>${E(a.allocation_date)} · ${E(a.source_currency)} ${N(C(a.source_cents))} → ${E(a.target_currency)} ${N(C(a.target_cents))} · ${E(L(a.status))} ${a.status==='Active'&&may('finance','edit')?btn('Reverse Allocation','배정 취소',`reverse('allocations',${a.id})`):''}</p>`).join('')}${s.refunds.map(r=>`<p>${E(r.refund_date)} · ${E(r.currency)} ${N(C(r.received_cents))} · ${E(r.reference)} · ${E(L(r.status))} <a href="/uploads/${E(r.evidence_file)}" target="_blank" rel="noopener">${E(T('Evidence','증빙'))}</a> ${r.status==='Active'&&may('finance','edit')?btn('Reverse Refund','환불 취소',`reverse('refunds',${r.id})`):''}</p>`).join('')}</div>`).join('')||`<p>${E(T('No agreed settlement obligations.','합의된 정산 의무가 없습니다.'))}</p>`}</section>`}
async function credit(id){try{const s=claim.settlements.find(s=>s.id===id),d=await api(B+'/suppliers/'+claim.supplier_id);dialogContext={action:'credit',s,purchases:d.eligible_purchases};dialog(T('Apply Supplier Adjustment Credit','공급업체 조정 크레딧 적용'),`<p>${E(s.currency)} ${N(C(s.available_cents))} · ${E(T('Non-cash allocation','비현금 배정'))}</p>${sel('target','Purchase','구매',[['',T('Select…','선택…')],...d.eligible_purchases.map(p=>[p.source_type+':'+p.id,p.purchase_no+' · '+p.currency])],'','required onchange="BOMReceiving44.creditTarget(this)"')}${field('amount','Credit amount','크레딧 금액',C(s.available_cents),'type="number" min="0.01" step="0.01" required')}<div data-credit-fx hidden>${field('currency_pair','Conversion pair','환산 통화쌍','','readonly')}${field('conversion_rate','Invoice currency per credit currency','크레딧 통화당 송장 통화','','type="number" min="0.0001" step="0.0001"')}${field('quote_reference','Conversion evidence reference','환산 증빙 참조')}</div>${field('allocation_date','Allocation date','배정일',new Date().toISOString().slice(0,10),'type="date" required')}${field('reason','Reason','사유','','required')}`,'saveCredit')}catch(e){error(e)}}
function creditTarget(el){const p=dialogContext.purchases.find(p=>p.source_type+':'+p.id===el.value),cross=p&&p.currency!==dialogContext.s.currency,root=el.form.querySelector('[data-credit-fx]');root.hidden=!cross;get(root,'currency_pair').value=cross?dialogContext.s.currency+'/'+p.currency:'';for(const n of ['conversion_rate','quote_reference'])get(root,n).required=!!cross;}
async function saveCredit(e){e.preventDefault();if(!e.target.reportValidity())return;try{const b=fd(e.target),[type,id]=b.target.split(':');if(await mutate('/credits/'+dialogContext.s.id+'/allocate',{...b,source_type:type,source_id:Number(id)})){closeModal(true);await openCase(claim.id)}}catch(e){error(e)}}
async function refund(id){try{const s=claim.settlements.find(s=>s.id===id),accounts=await api('/api/v320/financial-accounts?status=Active');dialogContext={action:'refund',s,accounts};dialog(T('Record Actual Claim Refund','실제 클레임 환불 입금 기록'),`<p>${E(T('Record only money actually received. Refund due:','실제 입금된 금액만 기록하세요. 환불 예정액:'))} ${E(s.currency)} ${N(C(s.available_cents))}</p>${sel('payment_account_id','Receiving company account','입금 회사 계좌',[['',T('Select…','선택…')],...accounts.map(a=>[a.id,a.name+' · '+a.currency])],'','required onchange="BOMReceiving44.refundAccount(this)"')}${sel('payment_method','Method','방법',[['Bank',T('Bank','은행')],['Cash',T('Cash','현금')]],'Bank')}${field('settled_amount','Claim amount settled ('+s.currency+')','정산 클레임 금액 ('+s.currency+')',C(s.available_cents),'type="number" min="0.01" step="0.01" required')}${field('received_amount','Actual account receipt amount','실제 계좌 입금액','','type="number" min="0.01" step="0.01" required')}${field('valuation_rate','KRW per receiving account currency','입금 계좌 통화당 원화','','type="number" min="0.0001" step="0.0001" required')}<div data-refund-fx hidden>${field('currency_pair','Claim / receiving currency pair','클레임 / 입금 통화쌍','','readonly')}${field('quote_reference','Conversion evidence reference','환산 증빙 참조')}</div>${field('refund_date','Actual receipt date','실제 입금일',new Date().toISOString().slice(0,10),'type="date" required')}${field('reference','Bank reference (cash optional)','은행 참조 (현금은 선택)')}${field('reason','Reason / notes','사유 / 메모','','required')}<label class="field"><span>${E(T('Actual receipt evidence','실제 입금 증빙'))}</span><input class="form-control" name="receipt" type="file" accept="image/*,.pdf" required></label>`,'saveRefund')}catch(e){error(e)}}
function refundAccount(el){const a=dialogContext.accounts.find(a=>String(a.id)===el.value);if(!a)return;const cross=a.currency!==dialogContext.s.currency;get(el.form,'valuation_rate').value=a.currency==='KRW'?'1':'';get(el.form,'payment_method').value=a.financial_account_type==='Cash'?'Cash':'Bank';el.form.querySelector('[data-refund-fx]').hidden=!cross;get(el.form,'currency_pair').value=cross?dialogContext.s.currency+'/'+a.currency:'';get(el.form,'quote_reference').required=cross;}
async function saveRefund(e){e.preventDefault();if(busy||!e.target.reportValidity())return;busy=true;try{const b=fd(e.target);if(!await confirmAction({title:T('Confirm Actual Refund','실제 환불 입금 확인'),message:`${b.refund_date}\n${T('Actual receipt','실제 입금')}: ${b.received_amount}\n${T('Claim amount settled','정산 클레임 금액')}: ${dialogContext.s.currency} ${b.settled_amount}\n${b.reference}`}))return;const data=new FormData(e.target);const url='/refunds/'+dialogContext.s.id+'/record',old=savedOperation(),key=e.target.dataset.operationKey||(e.target.dataset.operationKey=old?.url===url?old.key:crypto.randomUUID());data.set('idempotency_key',key);saveOperation({url,key});const r=await multipartApi(B+'/refunds/'+dialogContext.s.id+'/record',data,{headers:{'X-Idempotency-Key':key}});if(r){clearOperation();formDirty=false;closeModal(true);await openCase(claim.id)}}catch(e){if(await recover()){formDirty=false;closeModal(true);await openCase(claim.id)}else error(e)}finally{busy=false}}
async function report(type,id,format,button){if(button)button.disabled=true;try{const r=await fetch(B+'/'+type+'/'+id+'/report.'+format+'?lang='+currentLanguage,{headers:{Authorization:'Bearer '+token,'X-Business-Unit-ID':selectedUnitId,'X-Language':currentLanguage}});if(!r.ok){const d=await r.json();throw Error(d.error)}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='receiving-'+type+'-'+id+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){error(e)}finally{if(button)button.disabled=false}}
const policyLabels={inventory_variance_account_id:['Inventory correction variance (when needed)','재고 수정 차이 (필요 시)'],credit_account_id:['Adjustment-credit asset','조정 크레딧 자산'],receivable_account_id:['Refund receivable','환불 미수금'],loss_account_id:['Company loss expense','회사 손실 비용'],recovery_account_id:['Approved recovery offset','승인된 회수 상대 계정'],loss_offset_account_id:['Approved company loss offset','승인된 회사 손실 상대 계정'],fx_gain_account_id:['FX gain','외환 이익'],fx_loss_account_id:['FX loss','외환 손실']};
async function policyPage(){try{const d=await api(B+'/policy'),p=json(d.policy.policy_json);page(T('Receiving & Claims Policy','입고 및 클레임 정책'),`<p>${E(T('CEO authorization is required before financial claim rules become active. Ordinary receipts do not create financial claims.','재무 클레임 규칙 활성화 전에 CEO 승인이 필요합니다. 일반 입고는 재무 클레임을 생성하지 않습니다.'))}</p><form data-bom-no-review="1" onsubmit="BOMReceiving44.savePolicy(event)"><section class="card grid g2">${Object.entries(policyLabels).map(([k,l])=>sel(k,...l,[['',T('Select Accounting account','회계 계정 선택')],...d.accounts.map(a=>[a.id,a.code+' · '+a.name+' · '+a.account_type])],p[k]||'',k==='inventory_variance_account_id'?'':'required')).join('')}${sel('credit_available_stage','Credit available after','크레딧 사용 가능 시점',[['Approved',T('Authorized agreement','승인된 합의')],['Posted',T('Accounting Posting Control','회계 전기 통제')]],p.credit_available_stage||'Posted')}${sel('cross_currency_credit','Cross-currency credit allocation','다중 통화 크레딧 배정',[['false',T('Disabled pending decision','결정 전 비활성')],['true',T('Allow evidenced conversion','증빙 있는 환산 허용')]],String(p.cross_currency_credit===true))}${sel('cross_currency_refund','Cross-currency refund receipt','다중 통화 환불 입금',[['false',T('Disabled pending decision','결정 전 비활성')],['true',T('Allow evidenced conversion','증빙 있는 환산 허용')]],String(p.cross_currency_refund===true))}${field('accounting_treatment_note','Approved inventory / recovery policy','승인된 재고 / 회수 정책',p.accounting_treatment_note||'','required')}${field('reason','CEO decision note','CEO 결정 메모','','required')}</section>${err()}<div class="rc-footer"><button type="submit" class="btn primary">${E(T('Review & Authorize Policy','정책 검토 및 승인'))}</button></div></form>`)}catch(e){error(e)}}
async function savePolicy(e){e.preventDefault();if(!e.target.reportValidity())return;try{const b=fd(e.target),reason=b.reason;delete b.reason;b.cross_currency_credit=b.cross_currency_credit==='true';b.cross_currency_refund=b.cross_currency_refund==='true';if(await mutate('/policy',{policy:b,reason}))await policyPage()}catch(e){error(e)}}
const issueLabel=s=>({'Under investigation':T('Under investigation','조사 중'),'Awaiting approval':T('Awaiting approval','승인 대기'),'Awaiting supplier settlement':T('Awaiting supplier settlement','공급업체 정산 대기'),'Pending delivery':T('Pending delivery','입고 대기'),'Resolved':T('Resolved','해결됨')})[s]||L(s);
function flags(f={},target=''){const buttons=[];if(f.investigation)buttons.push(T('Under investigation','조사 중')+' · '+f.investigation);if(f.awaiting)buttons.push(T('Awaiting supplier settlement','공급업체 정산 대기')+' · '+f.awaiting);if(f.pending_delivery)buttons.push(T('Pending delivery','입고 대기')+' · '+f.pending_delivery);return buttons.map(label=>`<button type="button" class="btn small rc-issue-tag" onclick="${E(target||`BOMReceiving44.issueRoute(${f.issue_ids?.[0]||0})`)}">${E(label)}</button>`).join('')}
function issueCards(issues){return issues.length?`<section class="card"><h3>${E(T('Receiving Issues','입고 문제'))}</h3>${issues.map(i=>`<div class="rc-issue-row"><div><b>${E(i.purchase.purchase_no)} · #${i.id}</b><div>${E(issueLabel(i.status))}</div></div>${btn(i.status==='Resolved'?'View Issue':'Open Issue',i.status==='Resolved'?'문제 보기':'문제 열기',`issueRoute(${i.id})`)}</div>`).join('')}</section>`:''}
async function openCase(id){const c=await api(B+'/cases/'+id),advanced=new URLSearchParams(location.hash.split('?')[1]||'').get('advanced');if(c.issue_id&&!advanced)return issuePage(c.issue_id);return advancedCase(id)}
async function issuePage(id){const ticket=++epoch;await recover();const d=await api(B+'/issues/'+id);if(ticket!==epoch)return;state=await api(B+'/'+d.source_type+'/'+d.source_id+'/context');state.issue_receipt_id=d.receipt_id;page(T('Resolve Receiving Issue','입고 문제 해결')+' · '+d.purchase.purchase_no,`<div class="actions"><span class="badge">${E(issueLabel(d.status))}</span>${btn('Open Purchase','구매 열기',`purchase('${d.source_type}',${d.source_id})`)}${btn('Supplier Profile','공급업체 프로필',`supplier(${d.supplier_id})`)}${btn('Open Investigation Task','조사 작업 열기',`task(${d.task_id})`)}</div><div class="card"><h3>${E(d.supplier.name)}</h3><p>${E(T('Purchase','구매'))}: ${E(d.purchase.purchase_no)} · ${E(T('Receipt','입고'))}: ${E(d.receipt.receipt_no)} · ${E(d.receipt.receipt_date)}</p><p class="muted">${E(T('Receipt quantities are already saved. Resolve only the difference below.','입고 수량은 이미 저장되었습니다. 아래 차이만 해결하세요.'))}</p></div><details class="card"><summary>${E(T('Assignment & follow-up','담당자 및 후속 조치'))}</summary><form data-bom-no-review="1" onsubmit="BOMReceiving44.saveFollowUp(event,${d.id})">${sel('assigned_to','Assigned employee','담당 직원',d.employees.map(u=>[u.id,u.name]),d.assigned_to,'required')}${field('follow_up','Follow-up date','후속 조치일',d.follow_up||'','type="date"')}${field('reason','Follow-up note','후속 조치 메모','','required')}${err()}<button class="btn" type="submit">${E(T('Save Follow-up','후속 조치 저장'))}</button></form></details>${d.lines.map(x=>{const c=x.case,e=x.estimate,editable=x.decision!=='receipt_corrected'&&['Open','Under Investigation','Proposed Resolution','Rejected','Disputed'].includes(c.status)&&(may('purchases','edit')||may('finance','edit'));return `<section class="card" data-issue-case="${c.id}"><h3>${E(currentLanguage==='ko'?(e.line_name_ko||e.line_name):e.line_name)}</h3><span class="badge">${E(issueLabel(x.status))}</span><div class="rc-line-facts"><span>${E(T('Ordered','주문'))}: ${N(e.ordered_quantity)}</span><span>${E(T('Received now','이번 입고'))}: ${N(e.received_now)}</span><span>${E(T('Missing quantity','누락 수량'))}: ${N(Q(x.missing_q))} ${E(e.pricing_basis==='stock'?e.pricing_unit:state.lines.find(l=>l.id===x.source_line_id)?.unit||'')}</span>${x.missing_bags?`<span>${E(T('Missing bags','누락 포대'))}: ${N(x.missing_bags)}</span>`:''}${e.quality_quantity?`<span>${E(T('Inspection / rejected quantity','검사 / 거부 수량'))}: ${N(e.quality_quantity)} ${E(e.pricing_unit)}</span>`:''}<span>${E(T('Invoice unit price','송장 단가'))}: ${E(e.currency)} ${N(e.invoice_unit_price)} / ${E(e.invoice_unit)}</span><span>${E(T('Net settlement unit price','정산 순단가'))}: ${E(e.currency)} ${N(e.net_unit_price)} / ${E(e.pricing_unit)}</span><span><b>${E(T('Invoice-based estimate','송장 기준 예상액'))}: ${E(e.currency)} ${N(e.amount)}</b> · KRW ${N(e.krw_value)}</span></div>${editable?`<form data-bom-no-review="1" onsubmit="BOMReceiving44.saveDecision(event,${c.id},${c.revision})">${sel('responsibility','Investigation decision','조사 결정',[['',T('Select decision…','결정 선택…')],['later',T('Goods will arrive later','물품이 추후 도착')],['supplier',T('Supplier responsible','공급업체 책임')],['company',T('Our company accepts the loss / no supplier claim','당사 손실 부담 / 공급업체 클레임 없음')],['shared',T('Shared responsibility','책임 분담')],['carrier',T('Carrier / insurer responsible','운송사 / 보험사 책임')],...(may('inventory','edit')?[['correction',T('Receiving measurement was wrong — correct receipt','입고 측정 오류 — 입고 기록 수정')]]:[])],'','required onchange="BOMReceiving44.decisionFields(this)"')}<div data-decision-money hidden>${field('amount','Agreed claim amount ('+e.currency+')','합의 클레임 금액 ('+e.currency+')',e.amount,`type="number" min="0" step="0.01" data-estimate="${e.amount}" oninput="BOMReceiving44.decisionFields(this)"`)}<div data-decision-override hidden>${field('value_change_reason','Reason for changing the invoice estimate','송장 예상액 변경 사유')}</div><div data-decision-shared hidden><label class="field"><span>${E(T('Supplier share (%)','공급업체 부담 (%)'))}</span><input name="supplier_percent" type="range" min="0" max="100" step="0.01" value="50" oninput="BOMReceiving44.decisionFields(this)"></label>${field('precise_percent','Exact supplier percentage','정확한 공급업체 비율',50,'type="number" min="0" max="100" step="0.01" oninput="BOMReceiving44.share(this)"')}<div class="rc-bar" data-simple-bar></div><p data-simple-shares role="status"></p></div><div data-decision-method>${sel('settlement_method','Supplier settlement','공급업체 정산',[['Purchase Credit',T('Credit for a future purchase','향후 구매 크레딧')],['Invoice Reduction',T('Reduce unpaid invoice','미지급 송장 감액')],['Cash Refund',T('Refund money','환불')],['Replacement',T('Send replacement goods','대체품 발송')]],'Purchase Credit')}</div><div data-decision-carrier hidden>${field('counterparty','Carrier / insurer name','운송사 / 보험사 이름')}</div>${field('supplier_response','Agreement / supplier response','합의 / 공급업체 답변')}<label class="field"><span>${E(T('Agreement evidence','합의 증빙'))}</span><input name="evidence" type="file" multiple accept="image/*,.pdf"></label></div>${field('reason','Decision explanation','결정 설명','','required')}${err()}<div class="actions"><button type="submit" class="btn primary">${E(T('Review & Save Decision','결정 검토 및 저장'))}</button></div></form>`:''}${c.approvals.filter(a=>!['Executed','Rejected','Cancelled'].includes(a.status)).map(a=>`<p>${btn('Open Required Approval','필수 승인 열기',`approval(${a.id})`)}</p>`).join('')}${c.settlements.filter(s=>s.status!=='Reversed').map(s=>`<div class="rc-issue-row"><span>${E(L(s.method))} · ${E(s.currency)} ${N(C(s.amount_cents))}${s.method==='Cash Refund'?' · '+E(T('Still due','미입금'))+': '+N(C(s.balance_cents)):''}</span><div class="actions">${['Replacement','Later Delivery'].includes(s.method)&&s.available_delivery_q>0?btn('Receive Linked Delivery','연결 납품 입고',`source('${d.source_type}',${d.source_id},{replacement:${s.id}})`):''}${s.method==='Cash Refund'&&s.available_cents&&may('finance')?btn('Record Actual Refund','실제 환불 입금 기록',`issueRefund(${c.id},${s.id})`):''}${s.method==='Purchase Credit'&&s.available_cents&&may('finance','edit')?btn('Use Supplier Credit','공급업체 크레딧 사용',`issueCredit(${c.id},${s.id})`):''}</div></div>`).join('')}<details><summary>${E(T('History & advanced settlement','이력 및 고급 정산'))}</summary><p>${E(T('For mixed settlement, controlled amendments or reversals.','혼합 정산, 통제된 수정 또는 취소에 사용하세요.'))}</p>${btn('Open Detailed Case','상세 클레임 열기',`advanced(${c.id})`)}</details></section>`}).join('')}`);}
function decisionFields(el){const f=el.form,r=get(f,'responsibility').value,money=r&&!['later','correction'].includes(r),shared=r==='shared',carrier=r==='carrier';f.querySelector('[data-decision-money]').hidden=!money;f.querySelector('[data-decision-shared]').hidden=!shared;f.querySelector('[data-decision-carrier]').hidden=!carrier;f.querySelector('[data-decision-method]').hidden=!['supplier','shared'].includes(r);const input=get(f,'amount'),changed=money&&Math.abs(Number(input.value)-Number(input.dataset.estimate))>.005;f.querySelector('[data-decision-override]').hidden=!changed;get(f,'value_change_reason').required=changed;get(f,'counterparty').required=carrier;if(shared){const percent=Number(get(f,'supplier_percent').value),amount=Number(input.value||0),supplier=Math.round(amount*percent)/100;get(f,'precise_percent').value=percent;f.querySelector('[data-simple-bar]').innerHTML=`<span style="width:${percent}%;background:#066fd1"></span><span style="width:${100-percent}%;background:#f59f00"></span>`;f.querySelector('[data-simple-shares]').textContent=T('Supplier','공급업체')+': '+N(supplier)+' · '+T('Our company','당사')+': '+N(Math.round((amount-supplier)*100)/100);}get(f,'settlement_method').querySelector('[value=Replacement]').disabled=shared;}
function share(el){get(el.form,'supplier_percent').value=el.value;decisionFields(el)}
async function saveDecision(e,id,revision){e.preventDefault();if(busy||collecting||!e.target.reportValidity())return;collecting=true;try{const b=fd(e.target);if(b.responsibility==='correction'){const r=await mutate('/receipts/'+state.issue_receipt_id+'/reverse',{reason:b.reason},T('Reverse the entire original receipt, including its stock movements, then enter the corrected receipt. Dependent stock or financial records must be resolved first.','원래 입고 전체와 재고 이동을 취소한 뒤 올바른 입고를 다시 입력합니다. 연결된 재고 또는 재무 기록은 먼저 해결해야 합니다.'));if(r)await openCase(id);return;}b.method=b.settlement_method;delete b.settlement_method;delete b.precise_percent;b.revision=revision;b.evidence=await upload(e.target.elements.evidence.files,state.purchase);if(!b.evidence.length)delete b.evidence;if(b.responsibility==='company')b.method='Company Loss';const r=await mutate('/cases/'+id+'/decision',b,T('Save this decision using the existing approval and financial controls.','기존 승인 및 재무 통제를 적용하여 결정을 저장합니다.'));if(r)await openCase(id)}catch(e){error(e)}finally{collecting=false}}
window.BOMReceiving44={diagnostics:()=>({busy,collecting,source:state?.purchase?.id}),flags,issuePage,issueRoute:id=>BOMRouter.navigate('psSuppliers','issue',id),saveFollowUp:async(e,id)=>{e.preventDefault();if(!e.target.reportValidity())return;try{if(await mutate('/issues/'+id+'/follow-up',fd(e.target)))await issuePage(id)}catch(err){error(err)}},task:id=>BOMRouter.navigate('tasks','task',id),advanced:id=>BOMRouter.navigate('psSuppliers','claim',id,'',{params:{advanced:'1'}}),issueRefund:async(id,sid)=>{claim=await api(B+'/cases/'+id);return refund(sid)},issueCredit:async(id,sid)=>{claim=await api(B+'/cases/'+id);return credit(sid)},decisionFields,share,saveDecision,policyRoute:()=>BOMRouter.navigate('systemSettings','receiving-policy'),approval:id=>BOMRouter.navigate('approvals','approval',id),receiving,importReceive:id=>receiving('import',id),packReceive:id=>receiving('packaging',id),source,purchase,supplier,supplierPanel,case:caseRoute,openCase,line,prefill,saveReceipt,packSummary,newCase,disposition,reverse,reverseExcess,caseStatus,saveDialog,remove,calculate,percent,quantityShare,slider,addParty,addPlan,saveCase,agree,credit,creditTarget,saveCredit,refund,refundAccount,saveRefund,report,policyPage,savePolicy,close:()=>closeModal()};
