const oldSettingsShell=window.BOMSettingsShell319;if(oldSettingsShell)window.BOMSettingsShell319=function(...args){const result=oldSettingsShell.apply(this,args),root=args[0]||document.getElementById('content');if(me?.role==='CEO / Owner'&&root&&!root.querySelector('[data-rc-policy]'))root.insertAdjacentHTML('afterbegin',`<div class="actions" data-rc-policy>${btn('Receiving & Claims Policy','입고 및 클레임 정책','policyRoute()')}</div>`);return result};
