const oldImportDetail=window.psImportDetail;window.psImportDetail=async function(id){await oldImportDetail(id);const root=workflowSurfaceV324();if(!root)return;const c=await api(B+'/import/'+id+'/context');if(!root.isConnected)return;root.querySelectorAll('button[onclick*=psReceiveImport]').forEach(n=>n.remove());root.querySelectorAll('.ps-block-note,.ps-ready-note').forEach(n=>{if(/Shipment receiving is locked|Supplier payment fully cleared|공급업체 정산|공급업체 지급/.test(n.textContent))n.remove()});root.querySelector('.ps-actions')?.insertAdjacentHTML('afterbegin',btn(c.can_receive?'Receive Goods':'View Receiving History',c.can_receive?'물품 입고':'입고 이력 보기',`source('import',${id})`,c.can_receive?'primary':''));root.querySelector('[data-import-part=header]')?.insertAdjacentHTML('afterend',flags({pending_delivery:c.lines.some(l=>l.open_q>0&&l.previous_q>0)?1:0},`BOMReceiving44.source('import',${id})`)+issueCards(c.receiving_issues||[]));};
